function rerank(matches, query, ctx) {
  const active = matches.filter(p => {
    const specs = p.specifications || {};
    const status = String(specs.status || '').toLowerCase();
    const visibility = String(specs.visibility || specs.visibility_status || '').toLowerCase();
    if (status === 'draft' || status === 'private') return false;
    if (visibility === 'hidden') return false;
    if (p.hidden === true) return false;
    if (p.price === 0 || p.price === '0') return false;
    const cats = Array.isArray(p.categories) ? p.categories.join(' ') : '';
    const tags = Array.isArray(p.tags) ? p.tags.join(' ') : '';
    const title = p.title || '';
    const allText = (cats + ' ' + tags + ' ' + title).toLowerCase();
    if (allText.includes('neurobrave') || allText.includes('vibey')) return false;
    return true;
  });

  const q = (query || '').toLowerCase();
  const isStrapSearch = q.includes('רצוע') || q.includes('strap') || q.includes('band');

  if (isStrapSearch) {
    return active.map(p => p.id);
  }

  function isStrapOrAccessory(p) {
    const title = (p.title || '').toLowerCase();
    if (title.startsWith('רצועה') || title.startsWith('רצועת') || title.includes('רצועה ') || title.includes('רצועת ')) return true;
    if (title.includes('strap') || title.includes('band') || title.includes('quickfit')) return true;
    const cats = (p.categories || []).map(c => String(c).toLowerCase());
    if (cats.some(c => c.includes('רצועות') || c.includes('אביזרים'))) {
      if (!cats.some(c => c.includes('שעוני דופק') || c.includes('שעונים חכמים') || c.includes('שעוני ריצה') || c.includes('שעוני פרימיום') || c.includes('שעוני טריאתלון') || c.includes('שעוני צלילה'))) {
        return true;
      }
    }
    return false;
  }

  const instockWatches = [];
  const instockStraps = [];
  const outstockWatches = [];
  const outstockStraps = [];

  for (const p of active) {
    const isInstock = p.stockStatus === 'instock';
    const isStrap = isStrapOrAccessory(p);
    if (isInstock) {
      if (isStrap) instockStraps.push(p.id);
      else instockWatches.push(p.id);
    } else {
      if (isStrap) outstockStraps.push(p.id);
      else outstockWatches.push(p.id);
    }
  }

  return [...instockWatches, ...instockStraps, ...outstockWatches, ...outstockStraps];
}
